# >>> CHOICES
_choice_backup() {
    local -a flags=() dbs=()
    _helper_prisma_flags flags argc_project argc_branch
    if [[ -n ${argc_source_database:-${argc_database:-}} ]]; then
        dbs=("${argc_source_database:-$argc_database}")
    else
        mapfile -t dbs < <(_helper_prisma_databases)
    fi
    local d
    for d in "${dbs[@]:0:10}"; do
        _helper_prisma_labeled postgres backup list "${flags[@]}" "$d"
    done
}

_choice_branch() {
    local -a flags=()
    _helper_prisma_flags flags argc_project
    _helper_prisma_query '
        .envelope.result.branches[]?
        | "\(.name)\t\(.role // "")"
    ' branch list "${flags[@]}"
}

_choice_bucket() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch
    _helper_prisma_labeled bucket list "${flags[@]}"
}

_choice_connection() {
    local -a flags=() dbs=()
    _helper_prisma_flags flags argc_project argc_branch
    mapfile -t dbs < <(_helper_prisma_databases)
    local d
    for d in "${dbs[@]:0:10}"; do
        _helper_prisma_labeled postgres connection list "${flags[@]}" "$d"
    done
}

_choice_database() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch
    _helper_prisma_labeled postgres list "${flags[@]}"
}

_choice_env_assignment() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch argc_role
    [[ ${ARGC_CWORD:-} == *=* ]] && return 0
    _helper_prisma_query '.envelope.result.variables[]? | "\(.key)="' project env list "${flags[@]}"
}

_choice_env_key() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch argc_role
    _helper_prisma_query '.envelope.result.variables[]? | .key' project env list "${flags[@]}"
}

_choice_migration_target() {
    local -a flags=()
    _helper_prisma_flags flags argc_space
    _helper_prisma_query '.envelope.result.spaces[]?.migrations[]? | .name' migration list "${flags[@]}"
}

_choice_orm_authoring() {
    printf '%s\n' psl typescript
}

_choice_orm_target() {
    printf '%s\n' postgres mongodb
}

_choice_project() {
    _helper_prisma_labeled project list
}

_choice_ref() {
    _helper_prisma_query '.envelope.result.refs? // {} | keys[]' migration ref list
}

_choice_service() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch
    _helper_prisma_query '
        .envelope.result.services[]?
        | .id as $i
        | (.name // "") as $n
        | "\($i)\t\($n)",
          (if $n == "" or $n == $i then empty else "\($n)\t\($i)" end)
    ' service list "${flags[@]}"
}

_choice_version() {
    local -a flags=() svcs=()
    _helper_prisma_flags flags argc_project argc_branch
    mapfile -t svcs < <(_helper_prisma_services)
    local s
    for s in "${svcs[@]:0:10}"; do
        _helper_prisma_query '
            .envelope.result.versions[]?
            | "\(.id)\t\(.status // "")"
        ' service version list "${flags[@]}" "$s"
    done
}

_choice_workspace() {
    _helper_prisma_query '
        .envelope.result.items[]?
        | .workspaceId as $i
        | (.workspaceName // "") as $n
        | "\($i)\t\($n)",
          (if $n == "" or $n == $i then empty else "\($n)\t\($i)" end)
    ' auth workspace list
}

_helper_prisma_databases() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch
    if [[ -n ${argc_database:-} ]]; then
        printf '%s\n' "$argc_database"
    else
        _helper_prisma_query '.envelope.result.items[]? | .id' postgres list "${flags[@]}"
    fi
}

_helper_prisma_flags() {
    local -n _pflags=$1
    shift
    _pflags=()
    local _pf _pv
    for _pf in "$@"; do
        _pv="${!_pf:-}"
        [[ -n $_pv ]] && _pflags+=("--${_pf#argc_}" "$_pv")
    done
    return 0
}

_helper_prisma_labeled() {
    _helper_prisma_query '
        .envelope.result.items[]?
        | (.id // .workspaceId // "") as $i
        | (.label // .name // .workspaceName // "") as $n
        | select($i != "")
        | "\($i)\t\($n)",
          (if $n == "" or $n == $i then empty else "\($n)\t\($i)" end)
    ' "$@"
}

_helper_prisma_query() {
    local filter=$1
    shift
    local output
    output="$(prisma "$@" --quiet --json 2>/dev/null)" || return 0
    jq -b -r "$filter" <<<"$output" 2>/dev/null || return 0
}

_helper_prisma_services() {
    local -a flags=()
    _helper_prisma_flags flags argc_project argc_branch
    if [[ -n ${argc_service:-} ]]; then
        printf '%s\n' "$argc_service"
    else
        _helper_prisma_query '.envelope.result.services[]? | .id' service list "${flags[@]}"
    fi
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
